package za.ac.cput.service; import org.springframework.stereotype.Service; import za.ac.cput.domain.Register; import za.ac.cput.repository.RegisterRepository; @Service public class RegisterServiceImpl implements RegisterService{private final RegisterRepository repository; public RegisterServiceImpl(RegisterRepository repository){this.repository=repository;} public Register create(Register x){return repository.save(x);} public Register read(String id){return repository.findById(id).orElse(null);} public Register update(Register x){return repository.save(x);} public boolean delete(String id){if(repository.existsById(id)){repository.deleteById(id);return true;}return false;} public java.util.List<Register> findAll(){return repository.findAll();} }